Locates every substring (length 4-12) that equals its own
reverse complement, reporting 1-based position and length.
"""

_COMP = str.maketrans("ACGT", "TGCA")


def revcomp(seq: str) -> str:
    return seq.translate(_COMP)[::-1]


def reverse_palindromes(seq: str, min_len: int = 4, max_len: int = 12):
    """Return list of (position, length), 1-based, sorted by position then length."""
    results = []
    for length in range(min_len, max_len + 1):
        for start in range(len(seq) - length + 1):
            sub = seq[start:start + length]
            if sub == revcomp(sub):
                results.append((start + 1, length))
    return sorted(results)
