from revp import find_reverse_palindromes, revcomp

SEQ = "TCAATGCATGCGGGTCTATATGCAT"
EXPECTED = {(4, 6), (5, 4), (6, 6), (7, 4), (17, 4), (18, 4), (20, 6), (21, 4)}


def test_known_answer():
    assert set(find_reverse_palindromes(SEQ)) == EXPECTED


def test_sorted_by_position_then_length():
    out = find_reverse_palindromes(SEQ)
    assert out == sorted(out)


def test_homopolymer_yields_nothing():
    assert find_reverse_palindromes("AAAAAA") == []


def test_every_hit_is_self_revcomp():
    for pos, length in find_reverse_palindromes(SEQ):
        sub = SEQ[pos - 1:pos - 1 + length]
        assert sub == revcomp(sub), f"{sub!r} at ({pos}, {length}) is not a reverse palindrome"
